"""Boot context for the single-page app (www/mbc.html is generated by frontend/scripts/copy-html.mjs).

Every public and portal route is mapped here by hooks.website_route_rules. The context supplies:
- csrf_token for the SPA's API client,
- `boot` (window.mahanaim_boot): site name, session_info payload and public site settings, so the
  first paint needs no round-trip,
- SEO / OpenGraph meta for public paths from services.website.route_meta.
"""

from __future__ import annotations

from urllib.parse import quote

import frappe
import frappe.sessions
from frappe.utils import get_url

no_cache = 1
sitemap = 0

PORTAL_PREFIXES = ("applicant", "student", "lecturer", "admin", "sponsor")
PRIVATE_PREFIXES = (*PORTAL_PREFIXES, "signin", "forgot-password", "reset-password")
PORTAL_TITLES = {
	"applicant": "Admissions Portal",
	"student": "Student Portal",
	"lecturer": "Lecturer Portal",
	"admin": "Administration",
	"sponsor": "Sponsor Portal",
	"signin": "Sign in",
	"forgot-password": "Reset password",
	"reset-password": "Choose a new password",
}


def _path() -> str:
	req = getattr(frappe.local, "request", None)
	path = (getattr(req, "path", None) or "/").split("?")[0]
	return "/" + path.strip("/")


def _safe(fn, default=None):
	try:
		return fn()
	except Exception:
		frappe.log_error(title="mbc boot context")
		return default


def _json_safe(value):
	"""Round-trip through Frappe's encoder so dates, datetimes and Decimals reach `| tojson` as plain JSON."""
	return frappe.parse_json(frappe.as_json(value)) if value is not None else None


def get_context(context):
	from mahanaim.api.session import session_info

	path = _path()
	first = path.strip("/").split("/")[0] if path != "/" else ""

	context.no_cache = 1
	context.csrf_token = frappe.sessions.get_csrf_token()
	frappe.db.commit()  # persist the CSRF token on the session before the SPA uses it

	session = _safe(session_info, {"user": frappe.session.user, "roles": [], "portals": []})
	site = None
	if first not in PORTAL_PREFIXES:
		site = _safe(lambda: frappe.get_attr("mahanaim.api.website.site_settings")())

	settings = (session or {}).get("settings") or {}
	institution = settings.get("institution_name") or "Mahanaim Bible College"

	context.boot = _json_safe(
		{
			"sitename": frappe.local.site,
			"user": frappe.session.user,
			"session": session,
			"site": site,
			"socketio_port": frappe.conf.get("socketio_port") if frappe.conf.get("developer_mode") else None,
		}
	)

	meta = {}
	if first not in PRIVATE_PREFIXES:
		from mahanaim.services.website import route_meta

		meta = _safe(lambda: route_meta(path), {}) or {}

	title = meta.get("title")
	if first in PORTAL_TITLES:
		title = f"{PORTAL_TITLES[first]} · {institution}"
	context.site_name = institution
	context.meta_title = title or f"{institution} · Digital Campus"
	context.meta_description = meta.get("description") or (
		f"{institution} — theological training for pastors, missionaries and church leaders. "
		"Explore programmes, apply online, pay fees by M-Pesa and study on the Digital Campus."
	)
	image = meta.get("image")
	context.meta_image = get_url(image) if image and image.startswith("/") else image
	# request.path is already percent-decoded; re-quote it so the canonical URL is a valid URL
	# (the shell template also escapes every value it prints).
	context.canonical_url = get_url(quote(path, safe="/-._~")) if first not in PRIVATE_PREFIXES else None
	context.noindex = first in PRIVATE_PREFIXES
	context.og_type = meta.get("og_type") or "website"
	context.structured_data = _json_safe(meta.get("structured_data"))
	context.manifest = first if first in PORTAL_PREFIXES else "site"
	context.app_title = {"student": "MBC Student", "lecturer": "MBC Lecturer", "admin": "MBC Admin"}.get(
		first, "Mahanaim"
	)
	return context
